            for (uint8 i = 0; i < 2; ++i)
            {
                pos = me->GetNearPosition(15.0f, angle);
                me->CastSpellDelay(pos, SPELL_SUMMON_FLAMES, true, 4000);
                angle += 3.14f;
            }
        }
    }

    uint32 GetCombatSpell()
    {
        uint32 spellId = comboSpell[comboRand][comboCounter++];

        if (!IsMythicRaid())
            return spellId;

        switch (spellId)
        {
            case SPELL_FLAME_REND:
                return SPELL_EMPOWERED_FLAME_REND;
            case SPELL_FOE_BREAKER:
                return phase == PHASE_3 ? SPELL_EMPOWERED_FOE_BREAKER : spellId;
            case SPELL_SEARING_TEMPEST:
            {
                if (phase == PHASE_1)
                    return spellId;

                me->CastSpell(me, SPELL_EMPOWERED_SEARING_TEMPEST_AT, true);
                return SPELL_EMPOWERED_SEARING_TEMPEST;
            }
            default:
                return spellId;
        }
    }

    void UpdateAI(uint32 diff) override
    {
        if (!UpdateVictim())
            return;

        events.Update(diff);

        if (berserkTimer)
        {
            if (berserkTimer <= diff)
            {
                berserkTimer = 0;
                me->CastSpell(me, SPELL_BERSERK, true);
            }
            else
                berserkTimer -= diff;
        }

        if (CheckHomeDistToEvade(diff, 50.0f, centrPos.GetPositionX(), centrPos.GetPositionY(), centrPos.GetPositionZ()))
            return;

        if (me->HasUnitState(UNIT_STATE_CASTING))
            return;

        if (uint32 eventId = events.ExecuteEvent())
        {
            switch (eventId)
            {
				case EVENT_COMBO:
                    if (comboCounter == 5)
                    {
                        DefaultEvents();
                        break;
                    }
                    me->CastSpell(me, GetCombatSpell());
                    events.RescheduleEvent(EVENT_COMBO, IsMythicRaid() ? 3500 : 5000);
					break;
                case EVENT_SCORCHING_BLAZE:
                    DoCast(SPELL_SCORCHING_BLAZE_FILTER);
                    events.RescheduleEvent(EVENT_SCORCHING_BLAZE, 6500);
                    break;
                case EVENT_WAKE_OF_FLAME:
                    Talk(SAY_WAKE_OF_FLAME);
                    DoCastTopAggro(SPELL_WAKE_OF_FLAME_DUMMY);
                    events.RescheduleEvent(EVENT_WAKE_OF_FLAME, 24000);
                    break;
                case EVENT_PHASE_SWITCH:
                    me->StopAttack();
                    me->GetMotionMaster()->MovePoint(1, centrPos);
                    break;
                case EVENT_FLARE:
                    Talk(SAY_FLARE);
                    DoCast(SPELL_FLARE_FILTER);
                    if (!IsMythicRaid())
                        events.RescheduleEvent(EVENT_FLARE, 15000);
                    break;
                case EVENT_EMPOWERED_FLARE:
                    Talk(SAY_FLARE);
                    DoCast(SPELL_EMPOWERED_FLARE_FILTER);
                    if (!IsMythicRaid())
                        events.RescheduleEvent(EVENT_EMPOWERED_FLARE, 15000);
                    break;
                case EVENT_RAVENOUS_BLAZE:
                    DoCast(SPELL_RAVENOUS_BLAZE_FILTER);
                    events.RescheduleEvent(EVENT_RAVENOUS_BLAZE, 22000);
                    break;
            }
        }
        DoMeleeAttackIfReady();
    }
}

