    void DoAction(int32 const actionId)
    {
        if (eruption)
            return;

        if (actionId == ACTION_1)
        {
            eruption = true;
            moveTimer = 0;

            if (auto owner = me->GetAnyOwner())
                me->CastSpell(me, SPELL_BLAZING_ERUPTION, true, nullptr, nullptr, owner->GetGUID());

            me->StopMoving();
            me->AddDelayedEvent(500, [this] () -> void { me->DespawnOrUnsummon(); });
        }
    }

    void DamageTakenAfterScaling(Unit* attacker, uint32& damage, DamageEffectType dmgType) override
    {
        if (IsHeroicPlusRaid() && damage >= me->GetHealth(attacker))
        {
            damage = 0;

            if (!moltenRemnants && !eruption)
            {
                moltenRemnants = true;
                moveTimer = 0;
                me->StopMoving();
                me->CastSpell(me, SPELL_MOLTEN_REMNANTS_AT, true);
                me->SetFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_NOT_SELECTABLE | UNIT_FLAG_NON_ATTACKABLE);
                me->SetHealth(me->GetMaxHealth());
            }
        }
    }

    void OnApplyOrRemoveAura(uint32 spellId, AuraRemoveMode mode, bool apply) override
    {
        if (apply)
            return;

        if (spellId == SPELL_MOLTEN_REMNANTS_AT)
        {
            moveTimer = 1000;
            moltenRemnants = false;
            me->RemoveFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_NOT_SELECTABLE | UNIT_FLAG_NON_ATTACKABLE);
        }

        if (spellId == SPELL_CATALYZED && mode == AURA_REMOVE_BY_ENEMY_SPELL)
            me->CastSpell(me, SPELL_UNLEASHED_FLAME, true);
    }

    void UpdateAI(uint32 diff) override
    {
        if (moveTimer)
        {
            if (moveTimer <= diff)
            {
                moveTimer = 500;

                if (auto owner = me->GetAnyOwner())
                {
                    if (me->GetExactDist2d(owner) <= 10.0f)
                    {
                        DoAction(ACTION_1);
                        return;
                    }

                    if (!IsInDisable())
                        me->GetMotionMaster()->MovePoint(1, *owner, false);
                }
            }
            else
                moveTimer -= diff;
        }
    }
}

